<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\{Customer,License,Product,Release}; use App\Services\{AuditService,LicenseKeyService}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class LicenseController extends Controller { public function index(){return view('admin.resource',['title'=>__('ui.licenses'),'columns'=>['license_key_prefix','status','max_installations','expires_at'],'rows'=>License::with(['customer','product'])->latest()->paginate(20),'createRoute'=>route('licenses.create'),'actions'=>'licenses']);} public function create(){return view('admin.license-form',['customers'=>Customer::where('status','active')->get(),'products'=>Product::where('status','active')->get(),'releases'=>Release::where('status','published')->get()]);} public function store(Request $r,LicenseKeyService $keys,AuditService $audit){$data=$r->validate(['customer_id'=>'required|exists:customers,id','product_id'=>'required|exists:products,id','release_id'=>'nullable|exists:releases,id','max_installations'=>'required|integer|min:1|max:10000','expires_at'=>'nullable|date|after:today']);$raw=$keys->generate();$license=DB::transaction(fn()=>License::create(array_merge($data,['license_key_hash'=>$keys->hash($raw),'license_key_prefix'=>$keys->prefix($raw),'status'=>'created','created_by'=>$r->user()->id])));$audit->record('license.generated',$license,null,['uuid'=>$license->uuid,'status'=>'created']);return redirect()->route('licenses.index')->with('license_key',$raw)->with('success',__('ui.license_once'));} public function status(License $license,string $status,AuditService $audit){abort_unless(in_array($status,['active','suspended','revoked']),404);$before=$license->toArray();$license->update(['status'=>$status]);$audit->record('license.'.$status,$license,$before,$license->fresh()->toArray());return back()->with('success',__('ui.saved'));} }
